async function api(path,method='GET',body,headers={}){const r=await fetch('/v1'+path,{method,headers:{...(body!==undefined?{'Content-Type':'application/json'}:{}),...headers},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok){const e=new Error(data.message||'操作失败');e.status=r.status;e.data=data;throw e;}return data;}
function tell(s){$('#notice').textContent=s;$('#notice').style.display='block';setTimeout(()=>$('#notice').style.display='none',6000);}
function header(authenticated=true){return `<header>${authenticated&&course&&draft?`<div class="demo-breadcrumb"><span>${esc(draft.title)}</span><span>/</span><span>${esc(view==='graph'?(draft.outline.find(c=>c.id===graphChapter)?.title||'课程总览'):['read','edit'].includes(view)?(node()?.title||'课程内容'):'课程工作台')}</span><span>/</span><strong>${esc(viewLabels[view]||'课程工作台')}</strong></div>`:'<div><strong>知微</strong><small>连接知识 · 自主探索</small></div>'}<nav><span id="save-status"></span>${!publicId?(authenticated?'<button data-a="home">我的课程</button><button data-a="logout">退出</button>':'<span class="badge">教师登录</span>'):'<span class="badge">学生学习空间</span>'}</nav></header>`;}
function auth(){ $('#app').innerHTML=header(false)+`<form class="card auth"><span class="eyebrow">ZHIWEI / TEACHER</span><h1>让知识彼此连接</h1><p class="muted">登录教师工作台，创建属于你的课程。</p><label>邮箱<input name="email" type="email" required autocomplete="username"></label><label>密码（至少 10 位）<input name="password" type="password" minlength="10" required autocomplete="current-password"></label><div class="row"><button class="primary" name="login">登录</button><button name="register">注册新账号</button></div></form>`; $('form').onsubmit=async e=>{e.preventDefault();try{await api('/'+(e.submitter.name==='register'?'register':'login'),'POST',Object.fromEntries(new FormData(e.target)));await home();}catch(e){tell(e.message);}};}
async function home(){clearTimeout(timer);const [list,account]=await Promise.all([api('/courses'),api('/me')]);course=null;$('#app').innerHTML=header()+`<main class="hero course-home"><span class="eyebrow">COURSE STUDIO</span><h1>我的课程</h1><p class="muted">从空白课程开始。草稿独立保存，发布后学生才会看到。</p><div class="toolbar"><button class="primary" data-a="create">＋ 新建课程</button><button data-a="import">导入课程 ZIP</button></div><details class="storage-note"><summary>本机数据保存位置</summary><code>${esc(account.dataDirectory||'未提供')}</code></details><div class="list">${list.map(c=>`<button class="card home-course-card" data-course="${c.id}"><h2>${esc(c.title)}</h2><p>${c.published?'已发布':'未发布'} · 草稿修订 ${c.revision}</p><span>进入课程 →</span></button>`).join('')||'<p class="empty">还没有课程，创建第一门课程吧。</p>'}</div></main>`;}
async function load(cid){graphChapter=null;editingTemplate=null;clearTimeout(timer);course=cid;const c=await api('/courses/'+cid);draft=syncReferences(c.draft);revision=c.revision;dirty=false;conflict=false;nodeId=draft.nodes.find(n=>!n.archived)?.id;view='edit';const local=localStorage.getItem('pending:'+cid);render();if(local&&local!==JSON.stringify(draft))recoverPendingDialog(local);}
function recoverPendingDialog(raw){let local;try{local=JSON.parse(raw);if(local.schemaVersion!==1||!['nodes','outline','relations','templates'].every(k=>Array.isArray(local[k])))throw Error();}catch{tell('浏览器中有无法识别的未同步内容，已保留原始数据');return;}
 const el=dialog('发现尚未同步的编辑',`<p>浏览器保留了此前未保存成功的课程内容。请选择继续哪一份；当前已保存的课程已加载。</p><p>本地：${esc(local.title)} · ${local.nodes.length} 个知识点<br>已保存：${esc(draft.title)} · ${draft.nodes.length} 个知识点</p><p class="muted">继续本地编辑会将这份内容保存到当前课程。选择已保存内容则放弃浏览器中这份未同步编辑。</p><div class="row"><button class="primary" data-recover-pending>继续本地编辑</button><button data-use-saved>使用已保存内容</button></div>`);
 el.querySelector('[data-recover-pending]').onclick=event=>{event.stopPropagation();snapshot();draft=syncReferences(local);nodeId=draft.nodes.find(n=>!n.archived)?.id;changed();el.close();render();};el.querySelector('[data-use-saved]').onclick=event=>{event.stopPropagation();localStorage.removeItem('pending:'+course);el.close();};
}
function node(){return editingTemplate?draft.templates.find(t=>t.id===editingTemplate):draft?.nodes.find(n=>n.id===nodeId);}
function snapshot(){undo.push(JSON.stringify(draft));if(undo.length>40)undo.shift();redo=[];}
function changed(){syncReferences(draft);dirty=true;$('#save-status').textContent='待保存';localStorage.setItem('pending:'+course,JSON.stringify(draft));clearTimeout(timer);timer=setTimeout(()=>save().catch(e=>tell(e.message)),2000);}
let saveInFlight;
async function save(){while(saveInFlight)await saveInFlight;if(!dirty||conflict)return;const task=persistDraft();saveInFlight=task;try{await task;}finally{if(saveInFlight===task)saveInFlight=null;}if(dirty&&!conflict)await save();}
async function persistDraft(){if(!dirty||conflict)return;clearTimeout(timer);const payload=structuredClone(draft);$('#save-status').textContent='保存中…';try{const r=await api('/courses/'+course+'/draft','PUT',payload,{'If-Match':String(revision)});revision=r.revision;if(JSON.stringify(payload)===JSON.stringify(draft)){dirty=false;localStorage.removeItem('pending:'+course);}$('#save-status').textContent=dirty?'待保存':'已保存 · 修订 '+revision;}catch(e){if(e.status===412){conflict=true;e.message='保存冲突：当前内容已保留在浏览器。请刷新页面后选择继续本地编辑或使用已保存内容。';}$('#save-status').textContent=e.status===412?'保存冲突 · 编辑内容已保留':navigator.onLine?'保存失败':'离线未保存';throw e;}}
function collapsedChapters(){try{return new Set(JSON.parse(localStorage.getItem('collapsed:'+course)||'[]'));}catch{return new Set();}}
function toggleChapter(id){const collapsed=collapsedChapters();collapsed.has(id)?collapsed.delete(id):collapsed.add(id);localStorage.setItem('collapsed:'+course,JSON.stringify([...collapsed]));render();}
function treeControls(kind,id){return publicId?'':`<span class="tree-handle" aria-hidden="true">⠿</span><span class="tree-tools"><button data-tree-move="-1" data-tree-kind="${kind}" data-tree-id="${id}" aria-label="上移">↑</button><button data-tree-move="1" data-tree-kind="${kind}" data-tree-id="${id}" aria-label="下移">↓</button>${kind==='chapter'?`<button data-edit-chapter="${id}" aria-label="编辑章节">✎</button>`:''}</span>`;}
function outline(parent=null,prefix=''){
 const chapters=draft.outline.filter(x=>(x.parent||null)===parent),nodes=draft.nodes.filter(n=>!n.archived&&(n.chapter||null)===parent),collapsed=collapsedChapters();
 return chapters.map((x,i)=>{const number=prefix+(i+1),closed=collapsed.has(x.id);return `<div class="tree-branch"><div class="tree-row" data-tree-kind="chapter" data-tree-id="${x.id}" draggable="false">${treeControls('chapter',x.id)}<button class="chapter-toggle" data-toggle-chapter="${x.id}" aria-expanded="${!closed}" aria-label="${closed?'展开':'收起'}${esc(x.title)}">${closed?'▸':'▾'}</button><button class="tree-label" data-chapter-graph="${x.id}" title="查看章节知识图谱"><span class="tree-number">${number}</span><span>${esc(x.title)}</span></button></div>${closed?'':`<div class="tree-children">${outline(x.id,number+'.')}</div>`}</div>`;}).join('')+nodes.map((n,i)=>`<div class="tree-row ${n.id===nodeId?'selected':''}" data-tree-kind="node" data-tree-id="${n.id}" draggable="false">${treeControls('node',n.id)}<button class="tree-label" data-node="${n.id}"><span class="tree-number">${prefix+(chapters.length+i+1)}</span><span>${esc(n.title||'未命名')}</span></button></div>`).join('');
}
function renderCore(){const n=node();$('#app').innerHTML=header()+`<div class="shell"><aside data-course-id="${course}"><div class="demo-sidebar-brand"><div>知微<small>KNOWLEDGE STUDIO</small></div></div><div class="demo-course-label">${publicId?'我的学习空间':'我的课程工作台'}</div><div class="demo-course-card"><div><strong>${esc(draft.title)}</strong></div></div>${(publicId?['graph','progress','read']:['edit','graph','read','relations','assets','templates','trash']).map(v=>`<button data-view="${v}" class="${view===v?'active':''}">${({edit:'✎ 内容创作',graph:'◉ 知识图谱',read:'▤ 知识阅读台',relations:'↗ 关系维护',templates:'▦ 课程模板',assets:'▧ 素材库',history:'◷ 发布历史',trash:'♲ 回收站',progress:'✓ 学习进度'})[v]}</button>`).join('')}<hr><h4>课程章节</h4><div class="course-tree" aria-label="课程目录">${outline()}</div>${!publicId?`<div class="tree-root-drop" data-tree-kind="root" data-tree-id="root">拖到这里移出章节</div><button data-a="chapter">＋ 新建章节</button><div class="split-create"><button data-a="node">＋ 新建知识点</button><button data-a="default-template" aria-label="设置默认知识点模板" title="设置默认知识点模板">▾</button></div><small class="default-template-note">默认：${esc(defaultTemplateName())}</small>`:''}</aside><main data-scroll-key="${course}:${view}:${['edit','read'].includes(view)?editingTemplate||nodeId:''}" class="course-workspace view-${view} ${view==='graph'?'graph-workspace':''}"><div class="toolbar">${!publicId?'<button data-a="save" class="primary">保存草稿</button><button data-a="publish">检查并发布</button><button data-a="backup">本地备份</button><button data-a="restore-backup">备份恢复</button>':''}</div>${view==='edit'?editor(n):view==='graph'?graph():view==='read'?reading(n):view==='relations'?relations():view==='templates'?templatesView():view==='assets'?'<h1>课程素材库</h1><p>保存和复用课程中的图片、视频。PNG / JPEG / MP4，每文件上限 30 MB。</p><input class="asset-upload" type="file" id="asset-file" accept="image/png,image/jpeg,video/mp4"><div id="asset-list"></div>':view==='history'?'<h1>发布历史</h1><p>回滚只切换学生版本，保留最新草稿。</p><button data-a="withdraw">撤回公开访问</button><div id="releases"></div>':view==='trash'?trashView():progressView()}</main></div>`;if(!publicId)$('#save-status').textContent=conflict?'版本冲突':dirty?'待保存':'已保存 · 修订 '+revision;if(view==='assets')assetList();if(view==='history')releases();}
function editor(n){if(!n)return '<div class="empty">创建知识点，开始编写课程内容。</div>';return `<div class="row page-heading"><h1>${editingTemplate?'模板编辑':'知识点创作'}</h1>${editingTemplate?'<button data-a="finish-template">完成模板编辑</button>':''}<button data-a="undo">撤销</button><button data-a="redo">重做</button>${editingTemplate?'<span class="badge">只影响后续新建知识点</span>':'<button data-a="archive" class="danger">归档</button><button data-a="template">存为课程模板</button>'}</div><div class="editor-metadata"><label>标题<input data-field="title" value="${esc(n.title)}"></label><label>标签<input data-field="tags" value="${esc((n.tags||[]).join('，'))}"></label><label>所属章节<select data-field="chapter"><option value="">未分章</option>${draft.outline.map(x=>`<option value="${x.id}" ${n.chapter===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label></div>${relatedKnowledgeEditor(n)}${n.sections.map((s,i)=>`<section class="section" draggable="true" data-section="${s.sectionId}"><div class="row" data-section-header="${s.sectionId}"><input data-section-title="${s.sectionId}" value="${esc(s.title)}"><button data-move="${i}:-1">↑</button><button data-move="${i}:1">↓</button><button data-copy="${s.sectionId}">复制</button><button data-remove-section="${s.sectionId}">删除条目</button></div>${s.blocks.map(b=>`<div class="card" data-editor-block="${b.blockId}"><div class="row"><span class="badge">${esc(blockNames[b.type]||b.type)}</span><button data-move-block="${b.blockId}" data-delta="-1" aria-label="上移内容块">↑</button><button data-move-block="${b.blockId}" data-delta="1" aria-label="下移内容块">↓</button>${b.type==='reference'&&!editingTemplate?`<button data-reposition-reference="${b.blockId}">调整位置</button>`:''}<button data-remove-block="${b.blockId}">删除块</button></div>${['image','video'].includes(b.type)?mediaBlockEditor(b):['text','heading','formula','step'].includes(b.type)?`<textarea data-block="${b.blockId}">${esc(b.data.text)}</textarea>`:structuredBlockEditor(b)}</div>`).join('')}<div class="row"><select id="type-${s.sectionId}">${['text','image','video','reference','quiz'].map(t=>`<option value="${t}">${({text:'文字',heading:'标题',formula:'公式',step:'推导步骤',image:'图片',video:'视频',reference:'知识引用',quiz:'自测题'})[t]}</option>`).join('')}</select><button data-add-block="${s.sectionId}">＋ 内容块</button><button data-upload-section="${s.sectionId}" data-kind="image">上传 / 选择图片</button><button data-upload-section="${s.sectionId}" data-kind="video">上传 / 选择视频</button></div></section>`).join('')}<button data-a="section">＋ 新增条目</button>`;}
function relations(){return `<h1>知识关系</h1><p>前置知识：基础知识点 → 当前知识点；内容参考：两个知识点互相参考。</p><div class="row relation-compose"><select id="source">${options()}</select><select id="rel-type"><option value="reference">内容参考</option><option value="prerequisite">前置知识</option></select><select id="target">${options()}</select><input id="reason" placeholder="关联理由"><button data-a="relation">建立关系</button></div>${draft.relations.map(r=>`<div class="card relation-card">${esc(title(r.source))} ${r.type==='reference'?'↔':'→'} ${esc(title(r.target))} <span class="badge">${relationNames[r.type]}</span><p>${esc(r.reason)}</p>${r.referenceBlocks?.length?'<p class="muted">来自知识引用，删除关系时将同步删除对应引用块。</p>':''}<button data-place-relation="${r.id}">插入正文引用</button><button data-remove-relation="${r.id}">删除关系</button></div>`).join('')}`;}

function title(i){return draft.nodes.find(n=>n.id===i)?.title||'失效目标';}function options(){return draft.nodes.filter(n=>!n.archived).map(n=>`<option value="${n.id}">${esc(n.title)}</option>`).join('');}
function graph(){
 const q=sessionStorage.getItem('query')||'',numbers=directoryNumbers(draft),chapter=draft.outline.find(c=>c.id===graphChapter),model=knowledgeGraph(draft,chapter?.id,focus),scopeTitle=chapter?.title||draft.title,graphInstruction=focus?'已聚焦「'+title(focus)+'」 · 再次点击中心知识点进入学习 · 点击空白处返回上级目录':'点击知识点聚焦它的关系网络，再次点击进入学习。';
 return `<div class="graph-heading"><h1>知识图谱</h1><div class="graph-search"><span aria-hidden="true">⌕</span><input id="search" aria-label="搜索图谱知识点" placeholder="搜索名称或标签" value="${esc(q)}"><button data-a="clear-graph-search" aria-label="清空搜索">×</button></div></div><div class="demo-map-card"><div class="demo-graph-toolbar"><div class="demo-graph-intro"><p id="graph-instructions">${esc(graphInstruction)}</p></div><div class="demo-map-tools"><label class="graph-chapter-label"><span class="sr-only">探索范围</span> <select id="graph-chapter" aria-label="选择图谱章节"><option value="">全部章节</option>${focus&&!chapter?'<option value="__focus" selected disabled>知识点聚焦</option>':''}${draft.outline.map(c=>`<option value="${c.id}" ${c.id===graphChapter?'selected':''}>${numbers.chapters.get(c.id)} ${esc(c.title)}</option>`).join('')}</select></label><div class="graph-zoom"><button data-a="reset">全图 ⟳</button><button data-a="zoom-out" aria-label="缩小图谱">−</button><button data-a="zoom-in" aria-label="放大图谱">＋</button><button data-a="zoom-reset">${Math.round(zoom*100)}%</button></div></div></div><div class="graph-scroll graph-garden demo-graph-canvas ${chapter&&!focus?'chapter-graph':''} ${focus?'is-focused':'is-overview'}"><svg viewBox="0 0 1000 700" aria-label="${esc(chapter?chapter.title+'章节知识图谱':'课程知识图谱')}"><defs><radialGradient id="garden-fill"><stop offset="0%" stop-color="#edf5e8" stop-opacity=".7"/><stop offset="48%" stop-color="#f8fbf5" stop-opacity=".3"/><stop offset="100%" stop-color="#fbfcf8" stop-opacity="0"/></radialGradient><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="10" markerHeight="10" markerUnits="userSpaceOnUse" orient="auto"><path d="M1,1 L9,5 L1,9 Z" fill="${focus?'#67957b':'#b9c9bd'}"/></marker></defs><g class="graph-scenery" aria-hidden="true"><rect width="100%" height="100%" fill="#fbfcf8"/><rect class="demo-center-glow" width="100%" height="100%" fill="url(#garden-fill)"/>${focus?'<circle class="demo-focus-halo" r="118"/>':chapter?'<ellipse class="chapter-orbit inner-orbit"/><ellipse class="chapter-orbit outer-orbit"/>':'<ellipse class="chapter-orbit outer-orbit"/>'}</g>${model.edges.map(r=>{const undirected=['reference','comparison'].includes(r.type);return `<path class="graph-edge" fill="none" data-source="${r.source}" data-target="${r.target}" stroke="#becdbf" stroke-width="1.2" ${undirected?'stroke-dasharray="6 6"':'marker-end="url(#arrow)"'}><title>${esc(title(r.source)+' → '+title(r.target)+'：'+relationNames[r.type]+' '+(r.reason||''))}</title></path>`;}).join('')}${!focus?`<g class="chapter-center demo-center-label" aria-label="${esc(scopeTitle)}"><text class="chapter-center-number" y="-32" text-anchor="middle">${chapter?esc(chapterLabel(numbers.chapters.get(chapter.id))):''}</text><text class="chapter-center-name" y="18" text-anchor="middle" data-full-title="${esc(scopeTitle)}">${esc(scopeTitle)}</text><title>${esc(scopeTitle)}</title></g>`:''}${model.all.map(n=>{const [x,y]=model.positions.get(n.id),visible=model.visible.has(n.id),external=model.external?.has(n.id),chapterNumber=numbers.chapters.get(n.chapter),label=(external?'跨章 · ':'')+(chapterNumber?'第 '+chapterNumber+' 章':'未分章')+' · '+(numbers.nodes.get(n.id)||'');return `<g role="button" tabindex="${visible?'0':'-1'}" aria-hidden="${!visible}" aria-label="${esc(label+' '+n.title)}" data-focus="${n.id}" data-title="${esc(n.title)}" data-tags="${esc((n.tags||[]).join(' '))}" data-ring="${external?'external':'internal'}" class="${focus===n.id?'center':''} ${visible?'':'hidden-node'} ${external?'external-node':''} ${matchesQuery(n,q)?'search-match':q.trim()?'dim':''}" transform="translate(${x},${y})"><rect x="-85" y="-32" width="170" height="64"/><text class="graph-node-number" y="-12" text-anchor="middle">${esc(label)}</text><text class="graph-node-title" y="13" text-anchor="middle" data-full-title="${esc(n.title)}">${esc(n.title)}</text><text class="demo-node-enter" y="63" text-anchor="middle">再次点击 · 进入学习 →</text><title>${esc(label+' '+n.title)}</title></g>`;}).join('')}</svg></div><div class="demo-graph-foot"><span class="demo-legend"><i></i> 前置知识 <i class="dashed"></i> 内容参考</span><span id="graph-search-status" role="status"></span><span>${focus?model.visible.size-1+' 个直接关联 · 点击空白返回':chapter?model.internal.size+' 个本章知识点 · '+model.external.size+' 个跨章关联知识点':model.visible.size+' 个知识点 · 点击聚焦，再次点击学习'}</span></div></div>`;
}
function updateGraphSearch(){const q=$('#search')?.value||'';sessionStorage.setItem('query',q);document.querySelector('.graph-garden')?.classList.toggle('has-query',Boolean(q.trim()));let count=0;document.querySelectorAll('g[data-focus]').forEach(el=>{const matched=matchesQuery({title:el.dataset.title,tags:[el.dataset.tags]},q);el.classList.toggle('search-match',matched);el.classList.toggle('dim',Boolean(q.trim())&&!matched);if(matched&&el.getAttribute('aria-hidden')!=='true')count++;});const status=$('#graph-search-status');if(status)status.textContent=q.trim()?count+' 个匹配':'';}
document.addEventListener('input',event=>{if(event.target.id==='search')updateGraphSearch();});
document.addEventListener('change',event=>{if(event.target.id==='graph-chapter'){graphChapter=event.target.value||null;focus=null;render();}});
function renderBlock(b){const d=b.data;let html='';if(['text','formula','heading'].includes(b.type))html=b.type==='heading'?`<h3>${esc(d.text)}</h3>`:`<p>${esc(d.text)}</p>`;else if(b.type==='step')html=`<details><summary>${esc(d.title||'展开推导步骤')}</summary>${esc(d.text)}</details>`;else if(['image','video'].includes(b.type))html=b.type==='image'?`<img src="/v1/assets/${encodeURIComponent(d.assetId)}" alt="${esc(d.alt||'')}"><p>${esc(d.caption)}</p>`:`<video controls preload="metadata" src="/v1/assets/${encodeURIComponent(d.assetId)}"></video><p>${esc(d.caption)}</p>`;else if(b.type==='reference')html=`<button data-reference="${esc(d.target)}" data-anchor="${esc(d.anchor||'')}">${esc(title(d.target))} ↗</button>`;else if(b.type==='quiz')html=`<h3>${esc(d.question)}</h3><div class="quiz-options">${(d.options||[]).map(o=>`<button data-quiz="${b.blockId}" data-option="${esc(o.id)}">${esc(o.text)}</button>`).join('')}</div><p id="feedback-${b.blockId}" role="status"></p>`;else html='<p>此块暂不支持显示，原始数据已保留。</p>';return `<div class="block" id="b-${b.blockId}">${html}</div>`;}
function referenceSummaryView(nodeId){const groups=referenceSummary(draft,nodeId);return `<section class="knowledge-reference-summary" aria-label="知识引用汇总">${Object.entries(relationNames).map(([type,label])=>`<div class="reference-summary-row" data-reference-category="${type}"><strong>${label}：</strong><div class="reference-summary-links">${groups[type].map(n=>`<button data-reference="${n.id}">${esc(n.title)}</button>`).join('')||'<span class="muted">暂无</span>'}</div></div>`).join('')}</section>`;}
function article(n){return n?`<article data-reading-node="${n.id}"><span class="badge">${esc(n.tags.join(' / '))}</span><h1>${esc(n.title)}</h1>${n.sections.map(s=>`<section><h2>${esc(s.title)}</h2>${s.blocks.map(renderBlock).join('')}</section>`).join('')}${referenceSummaryView(n.id)}</article>`:'<p class="empty">请选择知识点。</p>';}
function reading(n){return `<section class="reader-workspace ${fullscreen?'fullscreen':''}"><div class="reading-title"><div class="reading-title-copy"><span class="reading-indicator"></span><strong>知识阅读台</strong><span>${reference?'并排参考，保留当前阅读位置':'点击关联知识，打开并排参考'}</span></div><div class="toolbar reader-tools"><button data-a="fullscreen">${fullscreen?'退出全屏':'全屏阅读'}</button><button data-view="graph">知识图谱</button><button data-a="complete">标记 / 取消已学会</button>${reference?'<button data-a="close-ref">关闭对照</button><button data-a="ref-back">返回参考</button>':''}</div></div><div class="reading-columns ${reference?'split':''}"><section class="reader-panel"><div class="reader-panel-bar"><span>当前知识点 / ${esc(n?.title||'尚未选择')}</span><small>独立阅读 · 保留位置</small></div><div class="pane">${article(n)}</div></section>${reference?`<section class="reader-panel reference-panel"><div class="reader-panel-bar"><span>↗ 关联参考 / ${esc(title(reference))}</span><small>独立滚动</small></div><div class="pane">${article(draft.nodes.find(n=>n.id===reference))}</div></section>`:''}</div></section>`;}
function progress(){try{return JSON.parse(localStorage.getItem('progress:'+course)||'[]');}catch{return [];}}
function trashView(){const archived=draft.nodes.filter(n=>n.archived);return `<h1>回收站</h1><p>已归档知识点保留原标识，可以恢复到课程中。</p>${archived.map(n=>`<div class="card"><span>${esc(n.title)}</span><button data-restore="${n.id}">恢复知识点</button></div>`).join('')||'<div class="empty">回收站为空，归档的知识点会显示在这里。</div>'}`;}
function progressView(){const model=learningModel(draft,progress());
 const card=n=>`<button class="progress-card card" data-node="${n.id}"><span class="progress-card-meta"><span class="progress-node-number">${esc(chapterLabel(model.numbers.chapters.get(n.chapter)))} · ${esc(model.numbers.nodes.get(n.id)||'')}</span><span class="${model.done.has(n.id)?'learned':'pending-status'}">${model.done.has(n.id)?'✓ 已学会':'○ 待学习'}</span></span><strong>${esc(n.title)}</strong><small>${esc((n.tags||[]).join(' / ')||'打开知识点学习')} ↗</small></button>`;
 const group=g=>{const visible=g.direct.filter(n=>learningFilter==='all'||(learningFilter==='learned')===model.done.has(n.id));return `<section class="learning-chapter" data-progress-chapter="${g.id}" data-total="${g.total}" data-pending="${g.pending}"><div class="learning-chapter-heading"><div><span class="eyebrow">${esc(chapterLabel(g.number))}</span><h2>${esc(g.title)}</h2></div><div class="chapter-learning-counts"><span>共 ${g.total} 个知识点${g.children.length?'（含子章节）':''}</span><span class="learned">已学会 ${g.learned}</span><span class="pending-status">待学习 ${g.pending}</span></div></div>${visible.length?`<div class="progress-grid">${visible.map(card).join('')}</div>`:!g.children.length?`<p class="learning-empty">${!g.total?'本章节暂未添加知识点':learningFilter==='pending'&&!g.pending?'本章节已全部学会':'没有符合当前筛选的知识点'}</p>`:''}${g.children.length?`<div class="learning-subchapters">${g.children.map(group).join('')}</div>`:''}</section>`;};
 return `<div class="page-intro"><span class="eyebrow">MY LEARNING</span><h1>学习进度</h1><p>按章节继续学习，学习记录保存在当前浏览器，不跨设备同步。</p></div><div class="progress-summary card"><div><strong>${model.learned}</strong><span> / ${model.total} 个知识点已学会 · 待学习 ${model.pending}</span></div><progress max="${Math.max(1,model.total)}" value="${model.learned}"></progress></div>${model.next?`<div class="learning-next card"><div><span class="eyebrow">建议继续学习</span><h3>${esc(model.next.title)}</h3><p>${esc(chapterLabel(model.numbers.chapters.get(model.next.chapter)))} · 依据前置关系推荐</p></div><button data-node="${model.next.id}" class="primary">继续学习 ↗</button></div>`:''}<div class="learning-filters" aria-label="筛选学习状态">${[['all','全部知识点'],['pending','待学习'],['learned','已学会']].map(([key,label])=>`<button data-learning-filter="${key}" aria-pressed="${learningFilter===key}" class="${learningFilter===key?'active':''}">${label}</button>`).join('')}</div><div class="learning-chapters">${model.groups.map(group).join('')||'<div class="empty">课程暂未添加知识点。</div>'}</div>`;
}
async function assetList(){try{const list=await api('/courses/'+course+'/assets');const target=$('#asset-list');if(!target)return;target.innerHTML=`<div class="media-grid">${list.map(a=>`<div class="media-card">${mediaPreview(a)}<strong>${esc(a.name)}</strong><span>${a.mime.startsWith('image/')?'图片':'视频'}</span><button data-rename-asset="${a.id}" data-name="${esc(a.name)}">修改名称</button><button data-delete-asset="${a.id}" class="danger">删除素材</button></div>`).join('')||'<p>还没有素材，可直接上传或在知识点内上传。</p>'}</div>`;}catch(e){tell(e.message);}}
async function releases(){const list=await api('/courses/'+course+'/releases');$('#releases').innerHTML=list.map((r,i)=>`<div class="card release-card"><div class="release-number">${String(list.length-i).padStart(2,'0')}</div><div><h3>课程发布版本 ${list.length-i}</h3><p>${new Date(r.created*1000).toLocaleString()}</p></div><button data-release="${r.id}">切换为学生当前版</button></div>`).join('')||'<div class="empty">还没有发布记录。完成课程后可在顶部发布。</div>';}
async function downloadBackup(){await save();if(conflict)throw Error('请先解决草稿保存冲突');const response=await fetch('/v1/courses/'+course+'/backup');if(!response.ok)throw Error((await response.json()).message);download(await response.blob(),draft.title.replace(/[\\/:*?"<>|]/g,'_')+'-本地备份-'+new Date().toISOString().replace(/[:.]/g,'-')+'.zip','application/zip');tell('本地备份已打包下载，包含草稿、模板、素材和当前学生发布版');}
function restoreBackupDialog(){
 const targetCourse=course,el=dialog('恢复当前课程的本地备份',`<p>选择此前通过“本地备份”下载的 ZIP 文件。恢复将覆盖当前课程的草稿、模板、素材和学生发布状态，课程链接保持不变。</p><p>请先下载当前课程的本地备份，以便需要时撤销恢复。</p><label>本地备份文件<input id="restore-file" type="file" accept=".zip,application/zip"></label><p class="form-error" role="alert"></p><button class="primary" id="restore-confirm" disabled>加载备份并恢复</button>`);
 const input=el.querySelector('#restore-file'),button=el.querySelector('#restore-confirm'),error=el.querySelector('.form-error');input.onchange=()=>button.disabled=!input.files.length;
 button.onclick=async()=>{button.disabled=true;input.disabled=true;try{if(course!==targetCourse)throw Error('课程已切换，请重新打开恢复窗口');await save();if(conflict)throw Error('请先解决草稿保存冲突');const response=await fetch('/v1/courses/'+course+'/restore',{method:'POST',headers:{'If-Match':String(revision),'Content-Type':'application/zip'},body:input.files[0]});const result=await response.json();if(!response.ok)throw Error(result.message);clearTimeout(timer);localStorage.removeItem('pending:'+course);undo=[];redo=[];el.close();await load(course);tell('课程已从本地备份恢复，课程链接保持不变');}catch(e){if(el.isConnected){error.textContent=e.message;button.disabled=false;input.disabled=false;}}};
}
function download(raw,name,type='application/json'){const url=URL.createObjectURL(new Blob([raw],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function remap(x){const text=JSON.stringify(x),ids=new Map();const collect=v=>{if(!v||typeof v!=='object')return;for(const [k,w]of Object.entries(v)){if(['id','sectionId','blockId'].includes(k)&&typeof w==='string')ids.set(w,id());else collect(w);}};collect(x);return JSON.parse(text,(k,v)=>typeof v==='string'&&ids.has(v)?ids.get(v):v);}
document.addEventListener('input',e=>{if(publicId)return;const t=e.target,n=node();if(t.matches('[data-field],[data-section-title],[data-block]')){snapshot();if(t.dataset.field)n[t.dataset.field]=t.dataset.field==='tags'?t.value.split(/[,，]/).filter(Boolean):t.value;if(t.dataset.sectionTitle)n.sections.find(s=>s.sectionId===t.dataset.sectionTitle).title=t.value;if(t.dataset.block)n.sections.flatMap(s=>s.blocks).find(b=>b.blockId===t.dataset.block).data.text=t.value;changed();}});
document.addEventListener('change',async e=>{try{if(e.target.dataset.json){const value=JSON.parse(e.target.value);snapshot();node().sections.flatMap(s=>s.blocks).find(b=>b.blockId===e.target.dataset.json).data=value;changed();}if(e.target.id==='asset-file'){const file=e.target.files[0];if(!file)return;tell('上传中…');await uploadMedia(course,file,file.name);tell('上传完成');assetList();}}catch(e){tell(e.message);}});
document.addEventListener('click',async e=>{const t=e.target.closest('button,[data-focus]');if(!t){if(e.target.closest('.graph-scroll')&&!e.target.closest('.graph-edge')){focus=null;render();}return;}try{if(t.dataset.learningFilter){learningFilter=t.dataset.learningFilter;return render();}if(t.dataset.course)return load(t.dataset.course);if(t.dataset.chapterGraph){graphChapter=t.dataset.chapterGraph;focus=null;view='graph';return render({treeReveal:{id:graphChapter,nearest:true}});}if(t.dataset.node){editingTemplate=null;nodeId=t.dataset.node;view=publicId?'read':'edit';reference=null;return render();}if(t.dataset.view){if(t.dataset.view==='templates')editingTemplate=null;view=t.dataset.view==='path'?'progress':t.dataset.view;return render();}if(t.dataset.focus){if(focus===t.dataset.focus){nodeId=focus;view='read';}else focus=t.dataset.focus;return render();}if(t.dataset.reference){if(reference)history.push(reference);reference=t.dataset.reference;render();if(t.dataset.anchor)document.getElementById('b-'+t.dataset.anchor)?.scrollIntoView();return;}if(t.dataset.quiz){const b=draft.nodes.flatMap(n=>n.sections.flatMap(s=>s.blocks)).find(b=>b.blockId===t.dataset.quiz);$('#feedback-'+b.blockId).textContent=(t.dataset.option===b.data.answer?'回答正确。':'再想一想。')+b.data.explanation;return;}if(t.dataset.release){await api('/courses/'+course+'/activate','POST',{releaseId:t.dataset.release});tell('学生版本已切换，草稿保留');return;}
if(t.dataset.toggleChapter){toggleChapter(t.dataset.toggleChapter);return;}
if(t.dataset.editChapter&&!publicId){chapterDialog(t.dataset.editChapter);return;}
if(t.dataset.treeMove&&!publicId){moveSibling(t.dataset.treeKind,t.dataset.treeId,Number(t.dataset.treeMove));return;}
if(!publicId&&await studioAction(t))return;
if(publicId){if(t.dataset.a==='clear-graph-search'){if($('#search'))$('#search').value='';updateGraphSearch();return;}if(t.dataset.a==='fullscreen'){fullscreen=!fullscreen;render();}if(t.dataset.a==='complete'){let p=progress();p=p.includes(nodeId)?p.filter(x=>x!==nodeId):[...p,nodeId];localStorage.setItem('progress:'+course,JSON.stringify(p));tell('学习进度已记录');}else if(t.dataset.a==='reset'){focus=null;graphChapter=null;render();}else if(t.dataset.a?.startsWith('zoom')){zoom=t.dataset.a==='zoom-reset'?1:Math.max(.75,Math.min(1.75,zoom+(t.dataset.a==='zoom-in'?.25:-.25)));render();}else if(t.dataset.a==='search'){sessionStorage.setItem('query',$('#search').value);render();}else if(t.dataset.a==='close-ref'){reference=null;render();}else if(t.dataset.a==='ref-back'){reference=history.pop()||null;render();}return;}
if(t.dataset.a==='undo'){if(undo.length){redo.push(JSON.stringify(draft));draft=JSON.parse(undo.pop());changed();render();}return;}if(t.dataset.a==='redo'){if(redo.length){undo.push(JSON.stringify(draft));draft=JSON.parse(redo.pop());changed();render();}return;}snapshot();const n=node();if(t.dataset.addBlock){const type=$('#type-'+t.dataset.addBlock).value;if(type==='image'||type==='video'){await insertMedia(t.dataset.addBlock,type);return;}let data={text:''};if(type==='reference')data={target:'',anchor:'',relationType:'reference'};if(type==='quiz'){const a=id(),b=id();data={question:'',options:[{id:a,text:''},{id:b,text:''}],answer:'',explanation:''};}n.sections.find(s=>s.sectionId===t.dataset.addBlock).blocks.push({blockId:id(),type,blockVersion:1,data});}
else if(t.dataset.removeSection)n.sections=n.sections.filter(s=>s.sectionId!==t.dataset.removeSection);
else if(t.dataset.removeBlock){if(!confirm('删除后指向此锚点的引用需要修复，是否继续？'))return;n.sections.forEach(s=>s.blocks=s.blocks.filter(b=>b.blockId!==t.dataset.removeBlock));}
else if(t.dataset.copy)n.sections.push(remap(n.sections.find(s=>s.sectionId===t.dataset.copy)));
else if(t.dataset.move){const [i,delta]=t.dataset.move.split(':').map(Number),j=i+delta;if(j>=0&&j<n.sections.length)[n.sections[i],n.sections[j]]=[n.sections[j],n.sections[i]];}
else if(t.dataset.removeRelation)removeRelationship(draft,t.dataset.removeRelation);
else if(t.dataset.restore)draft.nodes.find(n=>n.id===t.dataset.restore).archived=false;
else {const a=t.dataset.a;if(a==='home'){if(dirty)await save();return home();}if(a==='logout'){await api('/logout','POST',{});return auth();}if(a==='create'){const title=prompt('课程名称');if(title)return load((await api('/courses','POST',{title})).id);return;}if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.zip';input.onchange=async()=>{try{const r=await fetch('/v1/imports',{method:'POST',body:input.files[0]});const p=await r.json();if(!r.ok)throw Error(p.message);if(confirm('导入新课程：'+p.title+'，'+p.nodes+' 个知识点、'+p.assets+' 个素材？')){const c=await api('/imports/'+p.taskId,'POST',{});await load(c.id);}}catch(e){tell(e.message);}};input.click();return;}if(a==='save'){await save();return;}if(a==='publish'){await save();if(conflict)throw Error('先解决版本冲突');const result=await api('/courses/'+course+'/releases','POST',{}, {'If-Match':String(revision)});tell('发布成功');window.open('?course='+course,'_blank','noopener');return;}if(a==='withdraw'){await api('/courses/'+course+'/activate','POST',{releaseId:null});tell('已撤回公开访问');return;}if(a==='section')n.sections.push({sectionId:id(),title:'新条目',semanticKind:'custom',blocks:[]});else if(a==='archive'){if(!confirm('归档后，相关入站关系必须修复才能发布。是否继续？'))return;n.archived=true;nodeId=draft.nodes.find(x=>!x.archived)?.id;}else if(a==='undo'){undo.pop();if(undo.length){redo.push(JSON.stringify(draft));draft=JSON.parse(undo.pop());}}else if(a==='redo'){if(redo.length){undo.push(JSON.stringify(draft));draft=JSON.parse(redo.pop());}}else if(a==='reset')focus=null;else if(a==='search')sessionStorage.setItem('query',$('#search').value);else if(a?.startsWith('zoom'))zoom=a==='zoom-reset'?1:Math.max(.75,Math.min(1.75,zoom+(a==='zoom-in'?.25:-.25)));else if(a==='fullscreen')fullscreen=!fullscreen;else if(a==='close-ref')reference=null;else if(a==='ref-back')reference=history.pop()||null;else return;}
changed();render();}catch(e){tell(e.message+(e.data?.issues?'：'+e.data.issues.map(x=>x.message).join('；'):''));}});
let dragSection;document.addEventListener('dragstart',e=>{dragSection=e.target.closest('[data-section]')?.dataset.section;});document.addEventListener('dragover',e=>{if(e.target.closest('[data-section]'))e.preventDefault();});document.addEventListener('drop',e=>{const target=e.target.closest('[data-section]')?.dataset.section;if(!target||!dragSection||publicId)return;e.preventDefault();snapshot();const sections=node().sections,a=sections.findIndex(s=>s.sectionId===dragSection),b=sections.findIndex(s=>s.sectionId===target);if(a>=0&&b>=0)sections.splice(b,0,sections.splice(a,1)[0]);changed();render();});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-focus]')){e.preventDefault();const graphId=e.target.dataset.focus;e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));if(view==='graph')document.querySelector(`g[data-focus="${CSS.escape(graphId)}"]`)?.focus({preventScroll:true});}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
if(publicId){api('/public/'+publicId).then(c=>{course=publicId;draft=syncReferences(c.draft);nodeId=draft.nodes.find(n=>!n.archived)?.id;view='graph';render();}).catch(e=>{$('#app').innerHTML=header()+'<main>'+esc(e.message)+'</main>';});}else api('/me').then(home).catch(auth);
